#!/usr/bin/env bash
cd "$(dirname "$0")/.."
python3 tools/img.py ref/climber_hands.png "Continuity reference photograph for a film, 9:16. First-person view looking down at an adult South Asian man's own two forearms and hands held palms-down in front of him against plain grey rock. Medium-brown skin with natural pores, fine hair and short clean nails, natural five-finger proportions. He wears a mustard-yellow chunky wool outer garment whose sleeves end in identical ribbed knit cuffs of the same mustard colour at both wrists. His LEFT wrist (left side of the frame) has a single thin red cotton sacred thread. His RIGHT wrist (right side of the frame) has exactly two strands of brown rudraksha beads. Soft overcast daylight, documentary realism, sharp focus on the hands. No gloves, no rings, no watch, no text." > ref/climber.log 2>&1 &
python3 tools/img.py ref/shiva.png "Continuity reference portrait for a live-action devotional film, 9:16, waist-up, facing camera. An adult Indian male actor portraying Lord Shiva with restrained, realistic film makeup: calm, compassionate expression, natural human proportions, subtle ash-blue body paint with visible pores and dusty sacred-ash texture (not glossy, not plastic), natural brown eyes with no glow. Long dark matted jata hair piled into a topknot with a small silver crescent moon ornament, three thin white tripundra lines across the forehead with a small red dot, rudraksha bead necklaces and rudraksha armbands, a real-looking grey cobra coiled loosely around the neck, a tiger-stripe pattern cloth wrap at the waist. His LEFT hand (right side of the frame) holds a tall iron trident (trishul) with a small damru; his RIGHT hand is relaxed and empty. Overcast snowy mountain light, shot on a cinema camera, 50mm, natural skin, film grain. No glowing eyes, no text." > ref/shiva.log 2>&1 &
python3 tools/img.py ref/cliff.png "Location continuity reference photograph, 9:16: a steep icy granite cliff in the high Himalaya during a snowstorm at dusk. Two-thirds up the frame a narrow flat rock ledge covered in packed snow juts out from the cliff, about a metre deep; below it, a sheer rock face with cracks and ice runnels drops into blowing snow. In the far background, partly hidden by storm cloud, a pyramid-shaped snow peak like Mount Kailash. Realistic scale, varied snowflakes at different depths, cold blue-grey light, no people, no text." > ref/cliff.log 2>&1 &
wait; grep -L saved ref/*.log; echo done
